import bisect

def numerical_letter_grade(grades):
    if not isinstance(grades, list):
        raise TypeError("Input must be a list")

    thresholds = [4.0, 3.7, 3.3, 3.0, 2.7, 2.3, 2.0, 1.7, 1.3, 1.0, 0.7, 0.0]
    letters = ['A+', 'A', 'A-', 'B+', 'B', 'B-', 'C+', 'C', 'C-', 'D+', 'D', 'D-', 'E']

    result = []
    for g in grades:
        if not isinstance(g, (int, float)):
            raise TypeError("Each grade must be a number")
        if g < 0.0 or g > 4.0:
            raise ValueError("Grade must be between 0.0 and 4.0")

        if g == 4.0:
            result.append('A+')
        else:
            idx = bisect.bisect_right(thresholds, g)
            result.append(letters[idx])

    return result

