def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        if n % b != 0:
            return None
        return (0, n // b)
    if b == 0:
        if n % a != 0:
            return None
        return (n // a, 0)

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    scale = n // g
    x0 *= scale
    y0 *= scale

    # Adjust to non-negative solution if possible
    # General solution: x = x0 + k*(b/g), y = y0 - k*(a/g)
    bg = b // g
    ag = a // g

    # Find k such that x >= 0 and y >= 0
    # x >= 0 => k >= -x0/bg (if bg > 0) or k <= -x0/bg (if bg < 0)
    # y >= 0 => k <= y0/ag (if ag > 0) or k >= y0/ag (if ag < 0)

    import math
    if bg > 0:
        k_min = math.ceil(-x0 / bg)
    else:
        k_min = math.floor(-x0 / bg)  # careful with negative division

    if ag > 0:
        k_max = math.floor(y0 / ag)
    else:
        k_max = math.ceil(y0 / ag)

    if k_min > k_max:
        return None

    k = k_min
    x = x0 + k * bg
    y = y0 - k * ag
    return (x, y)

